        group.change_description(description); self._dirty = True
    ... same for permissions/subgroups/default ...
    if self._dirty:
        self._save()
        self._notify_listeners('permissions_changed' if ... else 'modified', group)

def remove_group(self, key, save=True, notify=True):
    group = self._to_group(key)
    if group is None: raise UnknownGroup(key)
    if not group.is_removable(): raise GroupUnremovable(key)
    del self._groups[key]
    self._dirty = True
    if save: self._save()
    if notify: self._notify_listeners('removed', group)

def find_group(self, key):
    if key is None: return None
    return self._groups.get(key)

